const {chromium}=require('/tmp/claude-0/-root-design/f13cfb4d-b71e-4ed8-960a-ee0a8c2a8818/scratchpad/pwnode/node_modules/playwright-core');
(async()=>{const browser=await chromium.launch({headless:true,executablePath:'/root/.cache/ms-playwright/chromium-1140/chrome-linux/chrome',args:['--no-sandbox','--no-zygote','--single-process','--headless=new']});const page=await browser.newPage({viewport:{width:1440,height:1000}});const errors=[];page.on('pageerror',e=>errors.push(e.message));await page.goto('file://'+process.cwd()+'/index.html',{waitUntil:'networkidle'});await page.screenshot({path:'/tmp/tidepool-desktop.png',fullPage:true});console.log('Desktop overflow:',await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth));await page.locator('[data-billing=\"annual\"]').click();console.log('Annual price:',await page.locator('#price-value').innerText());await page.locator('[data-billing=\"monthly\"]').click();console.log('Monthly price:',await page.locator('#price-value').innerText());await page.locator('.hero [data-tour]').click();await page.locator('[data-step=\"1\"]').click();await page.locator('#book-class').click();console.log('Class booking:',await page.locator('#book-class').innerText());await page.locator('[data-step=\"2\"]').click();await page.locator('#check-in').click();console.log('Check-in:',await page.locator('#check-in').innerText());await page.keyboard.press('Escape');await page.locator('.hero [data-demo]').click();console.log('Demo form open:',await page.locator('#demo-dialog').evaluate(e=>e.open));await page.locator('#demo-form [name=\"name\"]').fill('Jamie');await page.locator('#demo-form [name=\"gym\"]').fill('Test Gym');await page.locator('#demo-form [name=\"email\"]').fill('test@example.com');console.log('Form validity:',await page.locator('#demo-form').evaluate(e=>e.checkValidity()));await page.keyboard.press('Escape');await page.setViewportSize({width:390,height:844});await page.screenshot({path:'/tmp/tidepool-mobile.png',fullPage:true});console.log('Mobile overflow:',await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth));await page.locator('.mobile-toggle').click();console.log('Mobile menu:',await page.locator('#main-nav').isVisible());await page.getByRole('navigation').getByRole('link',{name:'Simple pricing'}).click();console.log('Mobile menu closed:',await page.locator('#main-nav').isHidden());console.log('Page errors:',errors);await browser.close()})().catch(e=>{console.error(e);process.exit(1)});
EOF
node /tmp/tidepool-check.cjs"

